"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[59411],{59411:function(e){e.exports=JSON.parse('{"content":"\\n<center>\\n<BookCard \\n          cover=\\"/assets/snippets/books/the-house-i-died-years-ago.png\\"\\n          title=\\"The House Where I Died\\"\\n          author=\\"Keigo Higashino\\"\\n          publisher=\\"Changhae\\"\\n          publishedDate=\\"2008-11-27\\"\\n          isbn=\\"9788979198478\\"\\n          rating=3.5\\n          tags=\\"mystery\\"\\n        />\\n</center>\\n\\n## Review\\nA high-density mystery that digs into the dark inner self and fragments of memory of humans in the extreme setting of only two characters and a limited space.  \\n<br>\\nThe process where the truth perfectly converges at the end by collecting the clues scattered in the work along with the reader clearly shows the author\'s characteristic plot construction ability.  \\n<br>\\nThe author himself mentioned this work as his ambitious project.  \\n<br>\\nBut the protagonist is frustrating.\\n"}')}}]);